package com.simpleengine.runtime;
import java.io.File;import java.util.ArrayList;import java.util.Collections;import java.util.List;
public final class JavaRuntimeManager{private final File root;public JavaRuntimeManager(File root){this.root=root;}public List<File> discover(String abi){List<File> r=new ArrayList<>();File p=JavaRuntime.resolve(root,abi);if(JavaRuntime.isUsable(p))r.add(p);collect(new File(root,"java"),abi,r);return Collections.unmodifiableList(r);}private void collect(File d,String abi,List<File> o){if(!d.isDirectory())return;File[] fs=d.listFiles();if(fs==null)return;for(File f:fs){if(f.isDirectory())collect(f,abi,o);else if(f.getName().equals("java")&&f.canExecute()&&f.getAbsolutePath().contains(File.separator+abi+File.separator))o.add(f);}}public File select(String abi){List<File> r=discover(abi);return r.isEmpty()?null:r.get(0);}}
